  const options = this.getOptions(); // getOptions\u4F1A\u81EA\u52A8\u5730\u5E2E\u6211\u4EEC\u5206\u6790this.query,\u7136\u540E\u628A\u53C2\u6570\u7684\u6240\u6709\u5185\u5BB9\u653E\u5728options\u91CC\u9762\u53BB
