// \u5F00\u542F\u7AEF\u53E3\uFF0C\u4F7F\u7528onmessage\u4E8B\u4EF6\u9ED8\u8BA4\u5F00\u542F\uFF0C\u53EF\u4EE5\u4E0D\u7528\u624B\u52A8\u8C03\u7528\u3002
worker.port.start();

// \u5728\u811A\u672C1\u4E2D\u5411sharedWorker\u53D1\u9001\u6D88\u606F
worker.port.postMessage(message);

// \u5728\u811A\u672C1\u4E2D\u63A5\u6536sharedWorker\u53D1\u9001\u7684\u6D88\u606F
worker.port.addEventListener('message', function(event) {
  const data = event.data;
  // \u5904\u7406\u6D88\u606F
})

worker.port.onmessage = function(event) {
  const data = event.data;
  // \u5904\u7406\u6D88\u606F
};

// \u5728\u811A\u672C2\u4E2D\u5411sharedWorker\u53D1\u9001\u6D88\u606F
worker.port.postMessage(message);

// \u5728\u811A\u672C2\u4E2D\u63A5\u6536sharedWorker\u53D1\u9001\u7684\u6D88\u606F
