const generatorPlugin = configs => {
  const plugins = [
    new webpack.DefinePlugin({
      'process.env.BASE_ENV': JSON.stringify(process.env.BASE_ENV), //\u628Aprocess.env.BASE_ENV\u6CE8\u5165\u5230\u4E1A\u52A1\u4EE3\u7801\u91CC\u9762
    }),
  ]
  return plugins;
}

commonConfig.plugins = generatorPlugin(commonConfig);
